import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const E=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Goryu","text":"The Go backend your AI gets right the first time.","tagline":"Describe the API — your agent builds it on Goryu, it compiles, and it's production-safe. Batteries-included, secure by default, and no-magic readable, so you can trust what your agent ships, not just run it.","image":{"src":"/logo.webp","alt":"Goryu logo"},"actions":[{"theme":"brand","text":"Build one with an agent","link":"/guide/getting-started"},{"theme":"alt","text":"Why Goryu?","link":"/guide/why-goryu"},{"theme":"alt","text":"GitHub","link":"https://github.com/arthurlch/goryu"}]},"features":[{"icon":"🎯","title":"Agents get it right the first time","details":"A small, regular API constrains codegen — fewer ways to call it means fewer ways to get it wrong. Go's compiler rejects the rest on the spot. If an LLM can't reliably write correct Goryu, the API is too clever — so it isn't."},{"icon":"🔒","title":"Secure by default","details":"Security headers, CSRF, JWT & sessions with unified invalidation, OAuth2/OIDC, passkeys, RBAC, and an audit log — on every response path. The agent physically can't skip the security basics."},{"icon":"🔋","title":"Batteries included, few dependencies","details":"Router, DB, validation, monitoring, health checks, graceful shutdown — wired from day one. Fewer libraries means fewer versions and APIs for an agent to hallucinate. One binary, zero assembly."},{"icon":"🔍","title":"No magic — readable enough to trust","details":"Explicit, readable Go. No reflection soup, no hidden control flow. You — or a non-technical reviewer — can read what the agent shipped and believe it's safe to deploy."},{"icon":"🤖","title":"AI-native","details":"SSE & typed streaming, Bind[T] + JSON Schema, token/cost metering, prompt caching, provider proxying, and eval recording. Build LLM backends without hand-rolling the plumbing."},{"icon":"⚡","title":"As fast as Gin","details":"Radix-tree router and optimized middleware chains — Gin-class throughput with 10× more built in. The simple REST case never pays for features it doesn't use."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789401078000}`),e={name:"index.md"};function h(l,s,p,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[t("",7)])])}const g=i(e,[["render",h]]);export{E as __pageData,g as default};
